use crate::common::{goto_definition_at, hover_response, open_php, references_response};
use std::fs;

use phpantom_lsp::Backend;
use tower_lsp::LanguageServer;
use tower_lsp::lsp_types::*;

/// A trimmed-down `.castor.stub.php`: braced namespace blocks holding
/// the helpers the task files call. Hidden *and* gitignored.
const CASTOR_STUB: &str = r#"<?php

// This file has been generated by castor. Do not edit it manually.

namespace Castor {
    function run(string $command): void {}
    function io(): void {}
}
"#;

/// A task file inside the hidden `.castor/` directory.
const DOCKER_TASKS: &str = r#"<?php

namespace docker;

function up(): void {}
"#;

/// The root `castor.php`, calling into both of the above.
const CASTOR_TASKS: &str = r#"<?php

use function Castor\io;
use function Castor\run;
use function docker\up;

function build(): void
{
    io();
    run('make build');
    up();
}
"#;

/// Build a Castor-shaped workspace whose `[indexing] include` is set to
/// `include`.
async fn castor_workspace(include: &[&str]) -> (Backend, tempfile::TempDir) {
    let dir = tempfile::tempdir().expect("failed to create temp dir");
    let root = dir.path();

    // `ignore` only honours `.gitignore` inside a git repository, so the
    // gitignored half of the fixture needs a repo to be realistic.
    fs::create_dir_all(root.join(".git")).unwrap();
    fs::write(root.join(".gitignore"), "/.castor.stub.php\n").unwrap();
    fs::write(root.join(".castor.stub.php"), CASTOR_STUB).unwrap();
    fs::create_dir_all(root.join(".castor")).unwrap();
    fs::write(root.join(".castor/docker.php"), DOCKER_TASKS).unwrap();
    fs::write(root.join("castor.php"), CASTOR_TASKS).unwrap();

    let entries: Vec<String> = include
        .iter()
        .map(|entry| format!("{entry:?}"))
        .collect::<Vec<_>>();
    fs::write(
        root.join(".phpantom.toml"),
        format!("[indexing]\ninclude = [{}]\n", entries.join(", ")),
    )
    .unwrap();

    let backend = Backend::new_test_with_workspace(root.to_path_buf(), Vec::new());
    backend.initialized(InitializedParams {}).await;

    let uri = Url::from_file_path(root.join("castor.php")).unwrap();
    open_php(&backend, &uri, CASTOR_TASKS).await;

    (backend, dir)
}

fn tasks_uri(dir: &tempfile::TempDir) -> Url {
    Url::from_file_path(dir.path().join("castor.php")).unwrap()
}

async fn goto(backend: &Backend, uri: &Url, line: u32, character: u32) -> Option<Location> {
    let response = goto_definition_at(backend, uri, line, character).await;

    match response {
        Some(GotoDefinitionResponse::Scalar(location)) => Some(location),
        Some(GotoDefinitionResponse::Array(mut locations)) => {
            (!locations.is_empty()).then(|| locations.remove(0))
        }
        _ => None,
    }
}

/// Without the option nothing changes: both hidden paths stay invisible.
/// This is the bug report, and it pins the default behaviour so the
/// option cannot silently become unconditional.
#[tokio::test]
async fn without_include_hidden_paths_stay_unindexed() {
    let (backend, dir) = castor_workspace(&[]).await;
    let uri = tasks_uri(&dir);

    assert!(
        goto(&backend, &uri, 9, 5).await.is_none(),
        "`run` is only declared in the gitignored stub"
    );
    assert!(
        goto(&backend, &uri, 10, 5).await.is_none(),
        "`up` is only declared in the hidden directory"
    );

    let mut diags = Vec::new();
    backend.collect_unknown_function_diagnostics(uri.as_str(), CASTOR_TASKS, &mut diags);
    assert_eq!(
        diags.len(),
        3,
        "io/run/up should all be unknown, got: {diags:?}"
    );
}

#[tokio::test]
async fn include_resolves_function_from_gitignored_stub() {
    let (backend, dir) = castor_workspace(&[".castor", ".castor.stub.php"]).await;
    let uri = tasks_uri(&dir);

    let location = goto(&backend, &uri, 9, 5)
        .await
        .expect("`run` should resolve to the included stub");
    assert_eq!(
        location.uri,
        Url::from_file_path(dir.path().join(".castor.stub.php")).unwrap()
    );
    assert_eq!(location.range.start.line, 5, "Castor\\run is on line 5");
}

#[tokio::test]
async fn include_resolves_function_from_hidden_directory() {
    let (backend, dir) = castor_workspace(&[".castor", ".castor.stub.php"]).await;
    let uri = tasks_uri(&dir);

    let location = goto(&backend, &uri, 10, 5)
        .await
        .expect("`up` should resolve inside the included hidden directory");
    assert_eq!(
        location.uri,
        Url::from_file_path(dir.path().join(".castor/docker.php")).unwrap()
    );
}

#[tokio::test]
async fn include_clears_unknown_function_diagnostics() {
    let (backend, dir) = castor_workspace(&[".castor", ".castor.stub.php"]).await;
    let uri = tasks_uri(&dir);

    let mut diags = Vec::new();
    backend.collect_unknown_function_diagnostics(uri.as_str(), CASTOR_TASKS, &mut diags);
    assert!(
        diags.is_empty(),
        "included declarations must clear the unknown-function diagnostics, got: {diags:?}"
    );
}

#[tokio::test]
async fn include_feeds_hover() {
    let (backend, dir) = castor_workspace(&[".castor", ".castor.stub.php"]).await;
    let uri = tasks_uri(&dir);

    // `io();` on line 8.
    let hover = hover_response(&backend, &uri, 8, 5)
        .await
        .expect("hover should resolve a function from the included stub");

    let text = match hover.contents {
        HoverContents::Markup(markup) => markup.value,
        other => panic!("expected markup hover, got: {other:?}"),
    };
    assert!(
        text.contains("function io()"),
        "hover should show the stub signature, got: {text}"
    );
}

/// A missing entry must not break indexing of the entries beside it.
#[tokio::test]
async fn include_tolerates_missing_entries() {
    let (backend, dir) = castor_workspace(&["does/not/exist", ".castor.stub.php"]).await;
    let uri = tasks_uri(&dir);

    assert!(
        goto(&backend, &uri, 9, 5).await.is_some(),
        "the stub should still be indexed alongside a stale entry"
    );
}

/// A Castor task file declares only functions, so no class index points
/// at it. Find-references still has to search it, or a call made from
/// one task file to another is missing from the results.
#[tokio::test]
async fn include_feeds_find_references_from_function_only_files() {
    let (backend, dir) = castor_workspace(&[".castor", ".castor.stub.php"]).await;
    let caller = dir.path().join(".castor/deploy.php");
    fs::write(
        &caller,
        "<?php\n\nnamespace deploy;\n\nfunction release(): void\n{\n    \\docker\\up();\n}\n",
    )
    .unwrap();

    let uri = tasks_uri(&dir);
    let locations = references_response(&backend, &uri, Position::new(10, 5), false)
        .await
        .unwrap_or_default();

    let caller_uri = Url::from_file_path(&caller).unwrap();
    assert!(
        locations.iter().any(|loc| loc.uri == caller_uri),
        "the call in the included task file should be found, got: {locations:?}"
    );
}

/// An included path fills gaps; it must not shadow a declaration the
/// rest of discovery found. Castor installed as a Composer dependency
/// declares its functions in an autoload file, and the generated stub
/// repeats them; the real declaration has to win.
#[tokio::test]
async fn include_does_not_shadow_composer_autoload_files() {
    let dir = tempfile::tempdir().expect("failed to create temp dir");
    let root = dir.path();
    fs::write(root.join("composer.json"), "{}\n").unwrap();
    let functions = root.join("vendor/jolicode/castor/src/functions.php");
    fs::create_dir_all(functions.parent().unwrap()).unwrap();
    fs::write(
        &functions,
        "<?php\n\nnamespace Castor;\n\nfunction run(string $command): void {}\n",
    )
    .unwrap();
    fs::create_dir_all(root.join("vendor/composer")).unwrap();
    fs::write(
        root.join("vendor/composer/autoload_files.php"),
        "<?php\n\n$vendorDir = dirname(__DIR__);\n$baseDir = dirname($vendorDir);\n\nreturn array(\n    'abc123' => $vendorDir . '/jolicode/castor/src/functions.php',\n);\n",
    )
    .unwrap();
    fs::write(root.join(".castor.stub.php"), CASTOR_STUB).unwrap();
    fs::write(root.join("castor.php"), CASTOR_TASKS).unwrap();
    fs::write(
        root.join(".phpantom.toml"),
        "[indexing]\ninclude = [\".castor.stub.php\"]\n",
    )
    .unwrap();

    let backend = Backend::new_test_with_workspace(root.to_path_buf(), Vec::new());
    backend.initialized(InitializedParams {}).await;

    let indexed = backend
        .autoload_function_index()
        .read()
        .get("Castor\\run")
        .cloned();
    assert_eq!(
        indexed.as_deref(),
        Some(functions.canonicalize().unwrap().as_path())
    );
}

/// A path outside the workspace is a library: its declarations resolve,
/// but nothing in it is the project's to rename.
#[tokio::test]
async fn include_outside_the_workspace_is_library_code() {
    let lib = tempfile::tempdir().expect("failed to create temp dir");
    fs::write(lib.path().join("docker.php"), DOCKER_TASKS).unwrap();
    let lib_path = lib.path().display().to_string();
    let (backend, dir) = castor_workspace(&[&lib_path]).await;
    let uri = tasks_uri(&dir);

    let location = goto(&backend, &uri, 10, 5)
        .await
        .expect("`up` should resolve into the included library");
    assert_eq!(
        location.uri,
        Url::from_file_path(lib.path().join("docker.php")).unwrap()
    );

    assert!(
        prepare_rename_up(&backend, uri).await.is_none(),
        "a function declared in library code must not be renamable"
    );

    // The same declaration inside the workspace is the project's own.
    let (backend, dir) = castor_workspace(&[".castor"]).await;
    assert!(
        prepare_rename_up(&backend, tasks_uri(&dir)).await.is_some(),
        "a function declared in an included workspace path is renamable"
    );
}

/// Prepare a rename on the `up()` call in `castor.php`.
async fn prepare_rename_up(backend: &Backend, uri: Url) -> Option<PrepareRenameResponse> {
    backend
        .prepare_rename(TextDocumentPositionParams {
            text_document: TextDocumentIdentifier { uri },
            position: Position {
                line: 10,
                character: 5,
            },
        })
        .await
        .unwrap()
}

/// The laravel-ide-helper files are skipped by default, and naming one
/// under `include` brings it back the way it does a gitignored file.
#[tokio::test]
async fn include_lifts_the_default_ide_helper_skip() {
    let dir = tempfile::tempdir().expect("failed to create temp dir");
    let root = dir.path();
    fs::write(
        root.join("_ide_helper.php"),
        "<?php\n\nnamespace {\n    class IdeHelperOnly {}\n}\n",
    )
    .unwrap();

    for (config, expected) in [
        ("[indexing]\nexclude = [\"!_ide_helper.php\"]\n", false),
        ("[indexing]\ninclude = [\"_ide_helper.php\"]\n", true),
    ] {
        fs::write(root.join(".phpantom.toml"), config).unwrap();
        let backend = Backend::new_test_with_workspace(root.to_path_buf(), Vec::new());
        backend.initialized(InitializedParams {}).await;

        assert_eq!(
            backend
                .fqn_uri_index()
                .read()
                .get("IdeHelperOnly")
                .is_some(),
            expected,
            "with {config:?}"
        );
    }
}
